from pysat.solvers import Glucose42
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

# Graceful labeling via SAT. 12 vertices, labels 0..21 (22 possible).
# Variables: x[v][l] = vertex v has label l. Each vertex: exactly-one label. Each label used at most once.
# Edge label variables: y[e][d] for d in 1..21. Exactly-one per edge, and each d used at most once.
# Link: x[u][a] & x[v][b] -> y[e][|a-b|].

vpool = IDPool()
n = 12
L = 22  # labels 0..21
D = 21  # diffs 1..21

edges = []
for g in range(4):
    a,b,c = 3*g, 3*g+1, 3*g+2
    edges += [(a,b),(a,c),(b,c)]
for g in range(3):
    for i in range(3):
        edges.append((3*g+i, 3*(g+1)+i))

def xv(v,l): return vpool.id(f'x_{v}_{l}')
def yv(e,d): return vpool.id(f'y_{e}_{d}')

clauses = []

# Each vertex exactly one label
for v in range(n):
    lits = [xv(v,l) for l in range(L)]
    clauses.append(lits)
    for i in range(len(lits)):
        for j in range(i+1,len(lits)):
            clauses.append([-lits[i],-lits[j]])

# Each label at most once
for l in range(L):
    lits = [xv(v,l) for v in range(n)]
    for i in range(len(lits)):
        for j in range(i+1,len(lits)):
            clauses.append([-lits[i],-lits[j]])

# Each edge exactly one diff
for e in range(len(edges)):
    lits = [yv(e,d) for d in range(1,D+1)]
    clauses.append(lits)
    for i in range(len(lits)):
        for j in range(i+1,len(lits)):
            clauses.append([-lits[i],-lits[j]])

# Each diff at most once across edges
for d in range(1,D+1):
    lits = [yv(e,d) for e in range(len(edges))]
    for i in range(len(lits)):
        for j in range(i+1,len(lits)):
            clauses.append([-lits[i],-lits[j]])

# Link: for each edge (u,v), for each pair (a,b), x_u_a & x_v_b -> y_e_|a-b|
for e,(u,v) in enumerate(edges):
    for a in range(L):
        for b in range(L):
            if a==b: continue
            d = abs(a-b)
            clauses.append([-xv(u,a), -xv(v,b), yv(e,d)])

solver = Glucose42()
for c in clauses:
    solver.add_clause(c)

print("solving...")
print(solver.solve())
model = solver.get_model()
mset = set(model)
labels = [None]*n
for v in range(n):
    for l in range(L):
        if xv(v,l) in mset:
            labels[v] = l
            break
print(labels)
eds = sorted(abs(labels[u]-labels[v]) for u,v in edges)
print(eds)
print(len(set(eds)), len(eds))
